#include "tight_phase_model.hpp"
#include "buffered_csv_reader.hpp"
#include "buffered_csv_writer.hpp"
#include <filesystem>
#include <ctime>
std::string_view trim(std::string_view s){auto a=s.find_first_not_of(" \r\n\t"),b=s.find_last_not_of(" \r\n\t");return a==s.npos?std::string_view{}:s.substr(a,b-a+1);}
int main(int argc,char**argv){try{std::string input,output,near;unsigned mode=2;int tx=30,ty=36;auto dir=std::filesystem::absolute(argv[0]).parent_path();std::string model=(dir/"tight-phase.bin").string();for(int i=1;i<argc;++i){std::string arg=argv[i];if(i+1==argc)throw std::runtime_error("Missing argument");if(arg=="-in")input=argv[++i];else if(arg=="-out")output=argv[++i];else if(arg=="--model")model=argv[++i];else if(arg=="--near")near=argv[++i];else if(arg=="--threshold-x")tx=std::stoi(argv[++i]);else if(arg=="--threshold-y")ty=std::stoi(argv[++i]);else if(arg=="--mode")mode=std::stoul(argv[++i]);else throw std::runtime_error("Unknown argument");}if(input.empty() || output.empty() || mode>2)throw std::runtime_error("Invalid arguments");auto norm=[](const std::string&p){return std::filesystem::weakly_canonical(std::filesystem::absolute(p));};for(auto&p:{input,model,near})if(!p.empty() && norm(output)==norm(p))throw std::runtime_error("Output aliases input");auto begin=std::clock();Graph graph;TightPhaseModel predictor(model,near);predictor.thresholds(tx,ty);FastPinParser parser;parser.enable_scan_coordinates();parser.enable_packed_port_index();double init=double(std::clock()-begin)/CLOCKS_PER_SEC;BufferedCsvReader reader(input);BufferedCsvWriter writer(output);std::string_view line;if(!reader.next(line) || trim(line)!="From,To")throw std::runtime_error("Invalid header");uint64_t rows=0;while(reader.next(line)){line=trim(line);if(line.empty())continue;auto comma=line.find(',');if(comma==line.npos || line.find(',',comma+1)!=line.npos)throw std::runtime_error("Invalid row");auto s=trim(line.substr(0,comma)),t=trim(line.substr(comma+1));auto delay=predictor.predict(graph,parser.pin(s),parser.pin(t),mode);if(delay>=INF)throw std::runtime_error("Unreachable query");writer.row(s,t,delay);++rows;}writer.finish();std::cerr<<"rows="<<rows<<" cpu_seconds="<<double(std::clock()-begin)/CLOCKS_PER_SEC<<" initialization_seconds="<<init<<'\n';}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
